SELECT 
FROM crm_event_nurture_sequence
WHERE tenant_id = #{tenantId}
  AND event_id = #{eventId}
  AND trigger_type = #{triggerType}
  AND enabled = '1'
  AND del_flag = '0'
LIMIT 1

mapper.update:
UPDATE crm_event_nurture_sequence
name = #{name}, enabled = #{enabled}, trigger_type = #{triggerType}, trigger_config = #{triggerConfig}::jsonb, exit_on_contact = #{exitOnContact}, update_by = #{updateBy}, update_time = NOW()
WHERE id = #{id} AND tenant_id = #{tenantId}
